Case 'epoch-invalidation-interruption-typed-recovery' {
 foreach($variant in 'missing','zero','one','raw'){
  Fixture ('invalidation-'+$variant) -Epoch -Seed {
   if($variant -ceq 'zero'){Set-ItemProperty $personalize EnableTransparency -Value 0 -Type DWord}
   elseif($variant -ceq 'one'){Set-ItemProperty $personalize EnableTransparency -Value 1 -Type DWord}
   elseif($variant -ceq 'raw'){Set-ItemProperty $personalize EnableTransparency -Value '%raw%' -Type ExpandString}
  }
  $before=Get-RecoveryRegistryValue (Get-Item $personalize).Name 'EnableTransparency'
  Open-RecoveryEpoch 'installed' -AssertIdle {}
  Register-RecoveryAuxiliaryIntent 'invalidation'
  $changed=if($variant -ceq 'zero'){1}else{0}
  Set-ItemProperty $personalize EnableTransparency -Value $changed -Type DWord
  Epoch-Restore
  Assert ((Get-RecoveryRegistryValue (Get-Item $personalize).Name 'EnableTransparency') -ceq $before) ('Interrupted invalidation did not restore '+$variant)
  $receipt=Read-RecoveryJson (Join-Path $epochDir 'auxiliary-EnableTransparency.json')
  Assert ($receipt.scenario -ceq 'invalidation') 'Receipt does not match real dispatcher scenario'
 }
